// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 timeOffset, uint256 blockNum) public {
        // bound inputs to reasonable ranges
        uint256 timestamp = block.timestamp + (timeOffset % 1e6) + 1;
        uint256 blockNumber = block.number + (blockNum % 15) + 1;

        vm.warp(timestamp);
        vm.roll(blockNumber);

        vm.deal(address(c), 10 ether);

        // make a call with 1 ether
        (bool success, ) = address(c).call{value: 1 ether}("");

        // rule: the call with 1 ether always reverts because the require checks for exactly 10 ether
        assertTrue(!success);
    }
}

